import React, { useEffect, useState, type FC, type ReactNode } from 'react';
import {
  getAuthUser,
  hasValidAuthToken,
  migrateLegacyActiveCompanyId,
} from '@linm-soft-org/linm-web-common-components';
import { isStandalone } from '../dev/isStandalone';
import { reconcileActiveCompanyForUser } from '../utils/reconcileActiveCompany';
import { syncActiveCompanyFromJwt } from '../utils/activeCompanyValidate';

let reconcileInFlight = false;

/** Sync + async tenant align — JWT allowlist vs stale `linm_active_company_id`. */
export async function runTenantReconcile(): Promise<void> {
  if (!hasValidAuthToken()) return;
  if (reconcileInFlight) return;

  reconcileInFlight = true;
  try {
    const user = getAuthUser();
    await migrateLegacyActiveCompanyId(user?.companyId);
    syncActiveCompanyFromJwt();
    reconcileActiveCompanyForUser(user);
  } finally {
    reconcileInFlight = false;
  }
}

/**
 * Block routes until tenant reconcile completes (embedded).
 * Standalone mock (no JWT): passes immediately; real JWT: reconcile before routes.
 */
export const TenantBootstrapGate: FC<{ children: ReactNode }> = ({ children }) => {
  const [ready, setReady] = useState(() => isStandalone && !hasValidAuthToken());

  useEffect(() => {
    let cancelled = false;
    let opened = false;
    let debounceTimer: ReturnType<typeof setTimeout> | null = null;

    const markReadyOnce = () => {
      if (!cancelled && !opened) {
        opened = true;
        setReady(true);
      }
    };

    const releaseAfterReconcile = () => {
      if (!hasValidAuthToken()) {
        if (isStandalone) markReadyOnce();
        return;
      }
      if (debounceTimer) clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        void runTenantReconcile().finally(markReadyOnce);
      }, 80);
    };

    releaseAfterReconcile();

    const onAuthEvent = () => releaseAfterReconcile();
    window.addEventListener('linm:auth:token-changed', onAuthEvent);

    const fallback = window.setTimeout(() => {
      if (hasValidAuthToken()) {
        releaseAfterReconcile();
      } else {
        markReadyOnce();
      }
    }, isStandalone ? 0 : 800);

    return () => {
      cancelled = true;
      if (debounceTimer) clearTimeout(debounceTimer);
      window.clearTimeout(fallback);
      window.removeEventListener('linm:auth:token-changed', onAuthEvent);
    };
  }, []);

  if (!ready) return null;
  return <>{children}</>;
};

